import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA kernel: fast fp16 LayerNorm (vectorized loads, block reduction)
# ------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TPB>
__global__ void layernorm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    int norm_size,          // number of elements per normalization group
    int outer_size,         // number of groups (batch)
    float eps) {

    const int tid = threadIdx.x;
    const int gid = blockIdx.x;               // one block per group
    if (gid >= outer_size) return;

    // ---- 1) per‑thread partial sums (vectorized half2) -----------------
    float sum  = 0.0f;
    float sumsq = 0.0f;

    // process two half values per iteration when possible
    int i = tid * 2;
    int step = TPB * 2;
    for (; i + 1 < norm_size; i += step) {
        // load two consecutive half values as __half2
        const __half2 h2 = __ldg(reinterpret_cast<const __half2*>(input + gid * norm_size + i));
        // convert to float2
        const float2 f2 = __half22float2(h2);
        sum   += f2.x + f2.y;
        sumsq += f2.x * f2.x + f2.y * f2.y;
    }
    // tail element if norm_size is odd
    if (i < norm_size) {
        float v = __half2float(__ldg(&input[gid * norm_size + i]));
        sum   += v;
        sumsq += v * v;
    }

    // ---- 2) block‑wide reduction (shared memory) -----------------------
    extern __shared__ float shmem[];           // 2 * TPB floats
    float* sh_sum   = shmem;
    float* sh_sumsq = shmem + TPB;

    sh_sum[tid]   = sum;
    sh_sumsq[tid] = sumsq;
    __syncthreads();

    // reduction tree
    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid]   += sh_sum[tid + stride];
            sh_sumsq[tid] += sh_sumsq[tid + stride];
        }
        __syncthreads();
    }

    // ---- 3) compute mean & inv_std (thread 0) -------------------------
    float mean = 0.0f, inv_std = 0.0f;
    if (tid == 0) {
        float total   = sh_sum[0];
        float totalSq = sh_sumsq[0];
        mean = total / static_cast<float>(norm_size);
        float var = totalSq / static_cast<float>(norm_size) - mean * mean;
        var = fmaxf(var, 0.0f);                 // guard against negative due to rounding
        inv_std = rsqrtf(var + eps);
        sh_sum[0]   = mean;    // reuse shared slots for broadcast
        sh_sumsq[0] = inv_std;
    }
    __syncthreads();

    mean    = sh_sum[0];
    inv_std = sh_sumsq[0];

    // ---- 4) write normalized output (vectorized stores) ---------------
    i = tid * 2;
    for (; i + 1 < norm_size; i += step) {
        const __half2 hin = __ldg(reinterpret_cast<const __half2*>(input + gid * norm_size + i));
        const float2 vin = __half22float2(hin);

        float2 out;
        out.x = (vin.x - mean) * inv_std;
        out.y = (vin.y - mean) * inv_std;

        if (weight) {
            const __half2 w2 = __ldg(reinterpret_cast<const __half2*>(weight + i));
            const float2 wf = __half22float2(w2);
            out.x *= wf.x;
            out.y *= wf.y;
        } else {
            // weight == nullptr -> treat as 1
        }
        if (bias) {
            const __half2 b2 = __ldg(reinterpret_cast<const __half2*>(bias + i));
            const float2 bf = __half22float2(b2);
            out.x += bf.x;
            out.y += bf.y;
        }

        __half2 hout = __float22half2_rn(out);
        reinterpret_cast<__half2*>(output + gid * norm_size + i)[0] = hout;
    }
    // tail element if needed
    if (i < norm_size) {
        float v = __half2float(__ldg(&input[gid * norm_size + i]));
        float norm = (v - mean) * inv_std;
        if (weight) {
            norm *= __half2float(__ldg(&weight[i]));
        }
        if (bias) {
            norm += __half2float(__ldg(&bias[i]));
        }
        output[gid * norm_size + i] = __float2half(norm);
    }
}

// ------------------------------------------------------------------
// wrapper
// ------------------------------------------------------------------
torch::Tensor layernorm_cuda(torch::Tensor input,
                             torch::Tensor weight,
                             torch::Tensor bias,
                             float eps) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be fp16");
    TORCH_CHECK(weight.is_cuda() && weight.dtype() == torch::kFloat16,
                "weight must be fp16 CUDA tensor");
    TORCH_CHECK(!bias.defined() || (bias.is_cuda() && bias.dtype() == torch::kFloat16),
                "bias must be fp16 CUDA tensor if defined");

    auto output = torch::empty_like(input);
    const int64_t norm_size = weight.numel();               // C = features*dim1*dim2
    const int64_t outer_size = input.numel() / norm_size;  // N = batch

    constexpr int TPB = 1024;
    const dim3 blocks(static_cast<unsigned int>(outer_size));
    const dim3 threads(TPB);
    const size_t shared_bytes = 2 * TPB * sizeof(float);   // sum + sumsq

    layernorm_kernel<TPB><<<blocks, threads, shared_bytes>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()) : nullptr,
        static_cast<int>(norm_size),
        static_cast<int>(outer_size),
        eps);

    return output;
}
"""

