        w_fp16 = self.ln.weight.to(torch.float16, non_blocking=True).contiguous()
        b_fp16 = self.ln.bias.to(torch.float16, non_blocking=True).contiguous()
        return layernorm_ext.layernorm_cuda(x_fp16, w_fp16, b_fp16, float(self.ln.eps))
